from collections import deque

def components(grid, connectivity=4, barrier=None):
 H,W=grid.shape
 seen=set(); comps=[]
 dirs=[(1,0),(-1,0),(0,1),(0,-1)]
 if connectivity==8: dirs += [(1,1),(1,-1),(-1,1),(-1,-1)]
 for r in range(H):
  for c in range(W):
   if (r,c) in seen or (barrier is not None and grid[r,c]==barrier): continue
   q=[(r,c)]; seen.add((r,c)); comp=[]
   for y,x in q:
    comp.append((y,x))
    for dy,dx in dirs:
     yy,xx=y+dy,x+dx
     if 0<=yy<H and 0<=xx<W and (yy,xx) not in seen and (barrier is None or grid[yy,xx]!=barrier):
      seen.add((yy,xx));q.append((yy,xx))
   comps.append(comp)
 return comps
